async function openEditProfileModal() {
  const userName = page_data.user.user;
  if (!userName || userName === "Guest") {
    toast.error("You must be logged in to edit your profile");
    return;
  }

  try {
    const userData = page_data.user;

    const dialogHtml = `
            <div class="edit-profile-form" style="display: flex; flex-direction: column; gap: 1rem;">
                <div class="form-group">
                    <label style="display: block; font-size: 13px; margin-bottom: 0.25rem; color: var(--ink-gray-7);">First Name</label>
                    <input type="text" id="edit-first-name" style="font-size: 14px; width: 100%; padding: 8px 6px; line-height: 1.15; border: 1px solid var(--f-dialog-border); border-radius: 8px; background-color: var(--f-dialog-bg); color: var(--f-dialog-text-body);" value="${userData.first_name || ""}">
                </div>
                <div class="form-group">
                    <label style="display: block; font-size: 13px; margin-bottom: 0.25rem; color: var(--ink-gray-7);">Last Name</label>
                    <input type="text" id="edit-last-name" style="font-size: 14px; width: 100%; padding: 8px 6px; line-height: 1.15; border: 1px solid var(--f-dialog-border); border-radius: 8px; background-color: var(--f-dialog-bg); color: var(--f-dialog-text-body);" value="${userData.last_name || ""}">
                </div>
                <div class="form-group">
                    <label style="display: block; font-size: 13px; margin-bottom: 0.25rem; color: var(--ink-gray-7);">Handle</label>
                    <input type="text" id="edit-handle" style="font-size: 14px; width: 100%; padding: 8px 6px; line-height: 1.15; border: 1px solid var(--f-dialog-border); border-radius: 8px; background-color: var(--f-dialog-bg); color: var(--f-dialog-text-body);" value="${userData.handle.split("@")[1] || ""}">
                </div>
                <div class="form-group">
                    <label style="display: block; font-size: 13px; margin-bottom: 0.25rem; color: var(--ink-gray-7);">Company</label>
                    <input type="text" id="edit-company" style="font-size: 14px; width: 100%; padding: 8px 6px; line-height: 1.15; border: 1px solid var(--f-dialog-border); border-radius: 8px; background-color: var(--f-dialog-bg); color: var(--f-dialog-text-body);" value="${userData.company || ""}">
                </div>
                <div class="form-group">
                    <label style="display: block; font-size: 13px; margin-bottom: 0.25rem; color: var(--ink-gray-7);">Designation</label>
                    <input type="text" id="edit-designation" style="font-size: 14px; width: 100%; padding: 8px 6px; line-height: 1.15; border: 1px solid var(--f-dialog-border); border-radius: 8px; background-color: var(--f-dialog-bg); color: var(--f-dialog-text-body);" value="${userData.designation || ""}">
                </div>
                <div class="form-group">
                    <label style="display: block; font-size: 13px; margin-bottom: 0.25rem; color: var(--ink-gray-7);">Bio</label>
                    <textarea id="edit-bio" rows="3" style="font-size: 14px; width: 100%; padding: 8px 6px; line-height: 1.15; border: 1px solid var(--f-dialog-border); border-radius: 8px; resize: vertical; background-color: var(--f-dialog-bg); color: var(--f-dialog-text-body);">${userData.bio || ""}</textarea>
                </div>
            </div>
        `;

    dialog({
      title: "Edit Profile",
      size: "md",
      html: dialogHtml,
      actions: [
        {
          label: "Save Changes",
          variant: "solid",
          onClick: async (close) => {
            const newFirstName =
              document.getElementById("edit-first-name")?.value;
            const newLastName =
              document.getElementById("edit-last-name")?.value;
            const newHandle = document.getElementById("edit-handle")?.value;
            const newCompany = document.getElementById("edit-company")?.value;
            const newDesignation =
              document.getElementById("edit-designation")?.value;
            const newBio = /** @type {HTMLTextAreaElement} */ (
              document.getElementById("edit-bio")
            )?.value;

            const updates = [];

            // Update User name if changed
            if (
              newFirstName !== userData.first_name ||
              newLastName !== userData.last_name
            ) {
              await frappeClient.setValue("User", userName, {
                first_name: newFirstName,
                last_name: newLastName,
              });
            }

            // Update Cafe User fields
            const userDataUpdates = {};
            const currentHandle = userData.handle
              ? userData.handle.includes("@")
                ? userData.handle.split("@")[1]
                : userData.handle
              : "";

            if (newHandle !== currentHandle) {
              userDataUpdates.handle = newHandle;
            }
            if (newCompany !== userData.company)
              userDataUpdates.company = newCompany;
            if (newDesignation !== userData.designation)
              userDataUpdates.designation = newDesignation;
            if (newBio !== userData.bio) userDataUpdates.bio = newBio;

            try {
              await frappeClient.setValue(
                "Cafe User",
                userName,
                userDataUpdates,
              );
              toast.success("Profile updated successfully");

              if (userDataUpdates.handle) {
                const url = new URL(location.href);
                url.pathname = url.pathname.replace(currentHandle, newHandle);
                setTimeout(() => (location.href = url.href), 500);
              } else {
                setTimeout(() => location.reload(), 500);
              }
              close();
            } catch (error) {
              console.log(error);
              toast.error(error.message || "Failed to update profile");
            }
          },
        },
        {
          label: "Cancel",
          onClick: (close) => close(),
        },
      ],
    });
  } catch (err) {
    console.error("Failed to fetch profile data:", err);
    toast.error("Could not load profile data");
  }
}

const MONTHS = [
  "Jan",
  "Feb",
  "Mar",
  "Apr",
  "May",
  "Jun",
  "Jul",
  "Aug",
  "Sep",
  "Oct",
  "Nov",
  "Dec",
];

function buildExperienceDialogHtml({
  titleLabel,
  orgLabel,
  currentlyLabel,
  item = {},
}) {
  const isCurrent = !!item.is_current;
  const monthOptions = (selectedVal) =>
    MONTHS.map(
      (m) =>
        `<option value="${m}" ${selectedVal === m ? "selected" : ""}>${m}</option>`,
    ).join("");
  const inputStyle = `font-size: 14px; width: 100%; padding: 8px 6px; line-height: 1.15; border: 1px solid var(--f-dialog-border); border-radius: 8px; background-color: var(--f-dialog-bg); color: var(--f-dialog-text-body);`;
  const labelStyle = `display: block; font-size: 13px; margin-bottom: 0.25rem; color: var(--ink-gray-7);`;

  return `
    <div class="add-experience-form" style="display: flex; flex-direction: column; gap: 1rem;">
      <div class="form-group">
        <label style="${labelStyle}">${titleLabel} *</label>
        <input type="text" id="exp-title" style="${inputStyle}" value="${item.title || ""}" required>
      </div>
      <div class="form-group">
        <label style="${labelStyle}">${orgLabel} *</label>
        <input type="text" id="exp-org" style="${inputStyle}" value="${item.organization || ""}" required>
      </div>
      <div style="display: flex; gap: 1rem;">
        <div class="form-group" style="flex: 1;">
          <label style="${labelStyle}">From Month</label>
          <select id="exp-from-month" style="${inputStyle}">
            <option value=""></option>
            ${monthOptions(item.from_month)}
          </select>
        </div>
        <div class="form-group" style="flex: 1;">
          <label style="${labelStyle}">From Year *</label>
          <input type="number" id="exp-from-year" placeholder="YYYY" style="${inputStyle}" value="${item.from_year || ""}" required>
        </div>
      </div>
      <div class="form-group" style="display: flex; align-items: center; gap: 0.5rem;">
        <input type="checkbox" id="exp-is-current" style="accent-color: var(--ink-gray-9);" ${isCurrent ? "checked" : ""}>
        <label for="exp-is-current" style="font-size: 13px; color: var(--ink-gray-7); margin: 0;">I currently ${currentlyLabel} here</label>
      </div>
      <div style="display: ${isCurrent ? "none" : "flex"}; gap: 1rem;" id="exp-to-date-container">
        <div class="form-group" style="flex: 1;">
          <label style="${labelStyle}">To Month</label>
          <select id="exp-to-month" style="${inputStyle}">
            <option value=""></option>
            ${monthOptions(item.to_month)}
          </select>
        </div>
        <div class="form-group" style="flex: 1;">
          <label style="${labelStyle}">To Year</label>
          <input type="number" id="exp-to-year" placeholder="YYYY" style="${inputStyle}" value="${item.to_year || ""}">
        </div>
      </div>
      <div class="form-group">
        <label style="${labelStyle}">Description</label>
        <textarea id="exp-description" rows="3" style="font-size: 14px; width: 100%; padding: 8px 6px; line-height: 1.15; border: 1px solid var(--f-dialog-border); border-radius: 8px; resize: vertical; background-color: var(--f-dialog-bg); color: var(--f-dialog-text-body);">${item.description || ""}</textarea>
      </div>
    </div>
  `;
}

async function openAddExperienceModal(type) {
  const userName = page_data.user.user;
  if (!userName || userName === "Guest") {
    toast.error("You must be logged in to add experience");
    return;
  }

  const isWork = type === "Work";
  const parentField = isWork ? "work_history" : "education";
  const titleLabel = isWork ? "Job Title" : "Degree";
  const orgLabel = isWork ? "Company" : "School/University";

  const dialogHtml = buildExperienceDialogHtml({
    titleLabel,
    orgLabel,
    currentlyLabel: isWork ? "work" : "study",
  });

  dialog({
    title: `Add ${isWork ? "Work History" : "Education"}`,
    size: "md",
    html: dialogHtml,
    actions: [
      {
        label: "Save",
        variant: "solid",
        onClick: async (close) => {
          const title = document.getElementById("exp-title")?.value;
          const organization = document.getElementById("exp-org")?.value;
          const from_month = /** @type {HTMLSelectElement} */ (
            document.getElementById("exp-from-month")
          )?.value;
          const from_year = document.getElementById("exp-from-year")?.value;
          const is_current = document.getElementById("exp-is-current")?.checked
            ? 1
            : 0;
          const to_month = /** @type {HTMLSelectElement} */ (
            document.getElementById("exp-to-month")
          )?.value;
          const to_year = document.getElementById("exp-to-year")?.value;
          const description = /** @type {HTMLTextAreaElement} */ (
            document.getElementById("exp-description")
          )?.value;

          if (!title || !organization || !from_year) {
            toast.error("Please fill all required fields");
            return;
          }

          if (!is_current) {
            if (!to_month && from_month) {
              toast.error("Please provide To Month");
              return;
            }
            if (!to_year) {
              toast.error("Please provide To Year");
              return;
            }
          }

          const payload = {
            parent: userName,
            parenttype: "Cafe User",
            parentfield: parentField,
            experience_type: type,
            title,
            organization,
            from_month,
            from_year: parseInt(from_year, 10),
            is_current,
            description,
          };

          if (!is_current) {
            payload.to_month = to_month;
            if (to_year) payload.to_year = parseInt(to_year, 10);
          }

          try {
            await frappeClient.post("Cafe User Experience", payload);
            toast.success(`${type} added successfully`);
            setTimeout(() => location.reload(), 500);
            close();
          } catch (error) {
            console.error(error);
            toast.error(error.message || "Failed to add experience");
          }
        },
      },
      {
        label: "Cancel",
        onClick: (close) => close(),
      },
    ],
  });

  // Toggle To Date fields based on Is Current checkbox
  setTimeout(() => {
    const isCurrentCheckbox = document.getElementById("exp-is-current");
    const toDateContainer = document.getElementById("exp-to-date-container");
    if (isCurrentCheckbox && toDateContainer) {
      isCurrentCheckbox.addEventListener("change", (e) => {
        if (e.target.checked) {
          toDateContainer.style.display = "none";
        } else {
          toDateContainer.style.display = "flex";
        }
      });
    }
  }, 100);
}

async function openEditWorkItemModal(workHistoryId) {
