function init() {
  const introContent = document.getElementById("intro-content");
  const showMoreBtn = document.getElementById("show-more-intro");
  if (introContent && showMoreBtn) {
    const computedStyle = getComputedStyle(introContent);
    const lineHeightVal = computedStyle.lineHeight;
    const lineHeight =
      lineHeightVal === "normal"
        ? parseFloat(computedStyle.fontSize) * 1.2
        : parseFloat(lineHeightVal);
    const lineCount = Math.round(introContent.scrollHeight / lineHeight);
    if (introContent.scrollHeight <= 560 && lineCount <= 3) {
      showMoreBtn.style.display = "none";
    }
  }

  const editButton = document.getElementById("edit-profile-button");
  if (editButton) {
    editButton.addEventListener("click", (e) => {
      e.preventDefault();
      e.stopPropagation();
      openEditProfileModal();
    });
  }

  const addWorkBtn = document.getElementById("add-work-history");
  if (addWorkBtn) {
    addWorkBtn.addEventListener("click", (e) => {
      e.preventDefault();
      e.stopPropagation();
      openAddExperienceModal("Work");
    });
  }

  const addEduBtn = document.getElementById("add-education-history");
  if (addEduBtn) {
    addEduBtn.addEventListener("click", (e) => {
      e.preventDefault();
      e.stopPropagation();
      openAddExperienceModal("Education");
    });
  }

  document.querySelectorAll(".edit-work-item").forEach((btn) => {
    btn.addEventListener("click", (e) => {
      e.preventDefault();
      e.stopPropagation();
      const id = btn.getAttribute("work-history-id");
      if (id) openEditWorkItemModal(id);
    });
  });

  document.querySelectorAll(".delete-work-btn").forEach((btn) => {
    btn.addEventListener("click", (e) => {
      e.preventDefault();
      e.stopPropagation();
      const id = btn.getAttribute("work-history-id");
      if (id) deleteWorkItem(id);
    });
  });

  document.querySelectorAll(".edit-education-item").forEach((btn) => {
    btn.addEventListener("click", (e) => {
      e.preventDefault();
      e.stopPropagation();
      const id = btn.getAttribute("education-history-id");
      if (id) openEditEducationItemModal(id);
    });
  });

  document.querySelectorAll(".delete-education-btn").forEach((btn) => {
    btn.addEventListener("click", (e) => {
      e.preventDefault();
      e.stopPropagation();
      const id = btn.getAttribute("education-history-id");
      if (id) deleteEducationItem(id);
    });
  });
}

init();
